import{_ as t,o as i,c as s,a3 as a}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse(`{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"Parcel to MQTT","text":"Développement arrêté","tagline":"Parcel Tracker est un projet bien plus abouti. C'est pourquoi nous mettons fin au développement de Parcel to MQTT. La documentation existante est conservée à titre d'archive.","actions":[{"theme":"brand","text":"Voir Parcel Tracker","link":"https://github.com/SoerenKaiser99/parcel_tracker"},{"theme":"alt","text":"GitHub","link":"https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/parcel_to_mqtt"}]},"features":[{"icon":"📦","title":"Statut du colis","details":"Statut du colis, dernier événement, destination et numéro d'envoi sous forme d'entités Home Assistant."},{"icon":"🚚","title":"DHL et Hermes pris en charge","details":"Gestion des comptes DHL, saisie manuelle de numéros d'envoi DHL et suivi des colis Hermes."},{"icon":"🧩","title":"Sections par transporteur","details":"Paramètres regroupés pour DHL, Hermes, GLS, DPD, UPS, Amazon Logistics, Deutsche Post (courriers) et FedEx."},{"icon":"📊","title":"Compteurs et emplacements","details":"Compteurs pour : total, en transit, en cours de livraison, en point relais, livré, retourné, problème rencontré et état inconnu."},{"icon":"🏠","title":"Découverte MQTT (MQTT Discovery)","details":"Home Assistant crée automatiquement les entités relatives aux colis, à leurs statuts et aux compteurs."},{"icon":"🔔","title":"Automatisations","details":"Les notifications peuvent être configurées via les automatisations standard de Home Assistant, en se basant sur les entités générées."}]},"headers":[],"relativePath":"fr/projects/parcel-to-mqtt/index.md","filePath":"fr/projects/parcel-to-mqtt/index.md","lastUpdated":1793123188000}`),r={name:"fr/projects/parcel-to-mqtt/index.md"};function o(n,e,l,u,c,p){return i(),s("div",null,[...e[0]||(e[0]=[a('<p><a id="index"></a><a id="statut"></a></p><div class="warning custom-block"><p class="custom-block-title">Développement arrêté</p><p>Parcel Tracker est un projet bien plus abouti. C&#39;est pourquoi nous mettons fin au développement de Parcel to MQTT ; nous invitons les personnes intéressées à consulter <a href="https://github.com/SoerenKaiser99/parcel_tracker" target="_blank" rel="noreferrer">Parcel Tracker par SoerenKaiser99</a>.</p><p>Le code source et la documentation précédente sont conservés sous forme d&#39;archive. Les fonctionnalités et instructions suivantes décrivent l&#39;état actuel de notre paquet.</p></div><h2 id="uberblick" tabindex="-1">Aperçu <a class="header-anchor" href="#uberblick" aria-label="Permalink to &quot;Aperçu {#uberblick}&quot;">​</a></h2><p>« Parcel to MQTT » est une application pour Home Assistant qui permet le suivi de colis via la fonctionnalité « MQTT Discovery » de Home Assistant.</p><p>La version actuelle prend en charge les listes de colis issues d&#39;un compte DHL, l&#39;ajout manuel de numéros de suivi DHL, ainsi que le suivi des colis Hermes. Les paramètres de l&#39;application sont regroupés par prestataire, ce qui permet à la configuration dans Home Assistant de rester concise, organisée par fournisseur.</p><div class="info custom-block"><p class="custom-block-title">Origine</p><p>Cette implémentation est adaptée de — et inspirée par — l&#39;adaptateur ioBroker <a href="https://github.com/TA2k/ioBroker.parcel" target="_blank" rel="noreferrer">TA2k/ioBroker.parcel</a>.</p><p>Le modèle d&#39;état commun s&#39;inspire des intégrations de suivi de colis pour Home Assistant <a href="https://github.com/ha-parcel-integrations" target="_blank" rel="noreferrer">ha-parcel-integrations</a>, distribuées sous licence MIT.</p></div><h2 id="fruhere-provider-roadmap-archiv" tabindex="-1">Feuille de route précédente (Archives) <a class="header-anchor" href="#fruhere-provider-roadmap-archiv" aria-label="Permalink to &quot;Feuille de route précédente (Archives) {#fruhere-provider-roadmap-archiv}&quot;">​</a></h2><p>Les points suivants décrivent l&#39;état d&#39;avancement antérieur et les plans initiaux. Cette feuille de route n&#39;est plus suivie :</p><ul><li>DHL : actif via un code de connexion par navigateur (<code>dhllogin://</code>) et ajout manuel de numéros de suivi ;</li><li>Amazon : préparé pour une utilisation avec e-mail, mot de passe et jeton OTP optionnel ;</li><li>Hermes : actuellement actif via la saisie manuelle de numéros de suivi ; La connexion au compte via le nom d&#39;utilisateur et le mot de passe de l&#39;application est prévue.</li><li>UPS : prêt à l&#39;emploi avec nom d&#39;utilisateur, mot de passe et numéros de suivi saisis manuellement.</li><li>GLS : prêt à l&#39;emploi avec numéros de suivi saisis manuellement et code postal de livraison ; le mécanisme de récupération des données (<em>polling</em>) attend l&#39;établissement d&#39;une session « Guest-Bearer » stable.</li><li>DPD : prêt à l&#39;emploi avec nom d&#39;utilisateur, mot de passe et numéros de suivi saisis manuellement, dès que le processus de connexion/session sera parfaitement stabilisé.</li><li>Deutsche Post (lettres) et FedEx : préparation effectuée pour une intégration ultérieure via des connecteurs dédiés, avec saisie manuelle des numéros de suivi.</li></ul><h2 id="weitere-seiten" tabindex="-1">Autres pages <a class="header-anchor" href="#weitere-seiten" aria-label="Permalink to &quot;Autres pages {#weitere-seiten}&quot;">​</a></h2><ul><li><a href="/fr/projects/parcel-to-mqtt/installation">Installation</a></li><li><a href="/fr/projects/parcel-to-mqtt/configuration">Configuration</a></li><li><a href="/fr/projects/parcel-to-mqtt/entities">Entités</a></li><li><a href="/fr/projects/parcel-to-mqtt/examples">Exemples</a></li></ul>',11)])])}const v=t(r,[["render",o]]);export{m as __pageData,v as default};
